head.script:
scwin.winSeq = 0;

scwin.onpageload = function() {
	windowContainer1.createWindow({
		"title" : "테스트1",
		"src" : "windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu1.xml",
		"windowId" : "window1",
		"frameMode" : "wframe"
	});
	windowContainer1.createWindow({
		"title" : "테스트2",
		"src" : "windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu2.xml",
		"windowId" : "window2",
		"frameMode" : "wframe"
	});
	windowContainer1.createWindow({
		"title" : "테스트3",
		"src" : "windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu3.xml",
		"windowId" : "window3",
		"frameMode" : "wframe"
	});
};

// windowMaxNum=5 상태에서 createWindow 호출 시 동작 확인
scwin.btnAddWindow_onclick = function() {
	scwin.winSeq++;
	var idx = scwin.winSeq;
	windowContainer1.createWindow({
		"title" : "신규" + idx,
		"src" : "windowContainer_windowMaxNum_WAEA-753_(WSQ-6228)_menu" + (((idx - 1) % 4) + 1) + ".xml",
		"windowId" : "extraWindow" + idx,
		"frameMode" : "wframe"
	});
};

// ▼ 신규 이벤트: windowMaxNum 초과 시 호출됨 (FIFO 재오픈)
// closeWindow는 내부적으로 100ms 후 실제 창 제거가 이루어지므로(currentWindowNum 감소도 이때 발생),
// 바로 createWindow를 호출하면 여전히 max 상태로 인식되어 onwindowmaxnumexceeded가 재발화(무한루프)된다.
// 따라서 close가 완전히 반영될 때까지 지연을 두고 재오픈한다.
scwin.windowContainer1_onwindowmaxnumexceeded = function(info) {
	windowContainer1.closeWindow(info.oldestWindowId);

	setTimeout(function() {
		windowContainer1.createWindow({
			"title" : info.title,
			"src" : info.src,
			"windowTitle" : info.windowTitle,
			"windowId" : info.windowId,
			"frameMode" : "wframe"
		});
	}, 150); // window.close 의 내부 지연(100ms) 보다 큰 값
};
